<?php
function aps_website_defaults(){return array('welcome_message'=>'Welcome to the Awuah Preparatory School community.','hero_title'=>'Small steps.|Bright futures.','hero_text'=>'Awuah Preparatory School is a warm learning community where every child is known, encouraged and inspired to grow with confidence.','school_phone'=>'','school_email'=>'');}
function aps_website_ensure($con){@mysqli_query($con,"CREATE TABLE IF NOT EXISTS tblwebsitecontent (content_key VARCHAR(80) NOT NULL PRIMARY KEY,content_value TEXT NOT NULL,updated_by VARCHAR(60) DEFAULT NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");@mysqli_query($con,"CREATE TABLE IF NOT EXISTS tblwebsiteannouncements (announcement_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,announcement_text TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'published',published_by VARCHAR(60) DEFAULT NULL,published_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_website_announcement (status,published_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");}
function aps_website_content($con){$data=aps_website_defaults();aps_website_ensure($con);$r=@mysqli_query($con,'SELECT content_key,content_value FROM tblwebsitecontent');while($r&&($row=mysqli_fetch_assoc($r))){if(array_key_exists($row['content_key'],$data))$data[$row['content_key']]=$row['content_value'];}return $data;}
function aps_website_escape($value){return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
function aps_gallery_items($con){aps_website_ensure($con);@mysqli_query($con,"CREATE TABLE IF NOT EXISTS tblwebsitegallery (gallery_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,image_path VARCHAR(255) NOT NULL,caption VARCHAR(180) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'published',uploaded_by VARCHAR(60) DEFAULT NULL,uploaded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_website_gallery(status,uploaded_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$items=array();$r=@mysqli_query($con,"SELECT * FROM tblwebsitegallery WHERE status='published' ORDER BY uploaded_at DESC");while($r&&($row=mysqli_fetch_assoc($r))){$items[]=$row;}return $items;}
?>
